const e = $json;
const workflowName = (e.workflow && (e.workflow.name || e.workflow.id)) || 'Unknown workflow';
const executionId = (e.execution && e.execution.id) || 'n/a';
const nodeName = (e.execution && e.execution.lastNodeExecuted) || (e.trigger && e.trigger.node) || 'unknown node';
const rawMsg = (e.execution && e.execution.error && e.execution.error.message)
  || (e.error && e.error.message)
  || (e.message)
  || 'Unknown error';
const timestamp = new Date().toISOString();
return [{ json: { executionId, workflowName, nodeName, timestamp, message: String(rawMsg).slice(0, 500) } }];
